e JSON structure more carefully for exchange rate data\nwith open('/app/resources/treasury_bulletin_1940_03.json', 'r') as f:\n    data = json.load(f)\n    \n# Look for any exchange-related content\ndef search_nested(d, path=''):\n    if isinstance(d, dict):\n        for k, v in d.items():\n            search_nested(v, f'{path}.{k}')\n    elif isinstance(d, list):\n        for i, item in enumerate(d):\n            search_nested(item, f'{path}[{i}]')\n    elif isinstance(d, str) and '1941' in d:\n        print(f'{path}: {d}')\n\nsearch_nested(data)\n\" 2>&1 | head -30"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
